// ===== AJUSTES =====
const NUMERO_DO_DONO = 'NUMERO_DO_DONO';
const TICKET_MEDIO = 150;      // R$ por consulta
const FALTAS_BASELINE = 5;     // faltas/semana ANTES da automação
const NOME_CLINICA = 'Clínica Sorriso';
// ====================

const so2 = (n) => String(n).padStart(2, '0');
const fmtBR = (d) => `${so2(d.getDate())}/${so2(d.getMonth() + 1)}/${d.getFullYear()}`;
const reais = (n) => n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

function parseDataBR(txt) {
  const p = String(txt || '').trim().split('/');
  if (p.length !== 3) return null;
  const d = new Date(Number(p[2]), Number(p[1]) - 1, Number(p[0]));
  return isNaN(d.getTime()) ? null : d;
}

const hoje = new Date();
hoje.setHours(0, 0, 0, 0);
const amanha = new Date(hoje);
amanha.setDate(amanha.getDate() + 1);

const consultas = $input
  .all()
  .map((i) => i.json)
  .filter((c) => c && c.data)
  .map((c) => ({ ...c, _d: parseDataBR(c.data), _s: String(c.status || '').trim() }))
  .filter((c) => c._d);

const mesmoDia = (a, b) => a && b && a.getTime() === b.getTime();
const diasEntre = (a, b) => Math.round((a - b) / 86400000);

// --- amanhã ---
const deAmanha = consultas.filter((c) => mesmoDia(c._d, amanha));
const confAmanha = deAmanha.filter((c) => c._s === 'confirmada');
const aguardAmanha = deAmanha.filter((c) => c._s === 'aguardando resposta' || c._s === 'agendada');
const cancAmanha = deAmanha.filter((c) => c._s === 'cancelada' || c._s === 'remarcada');

// --- últimos 7 dias (inclui hoje) ---
const semana = consultas.filter((c) => {
  const d = diasEntre(hoje, c._d);
  return d >= 0 && d <= 6;
});
const confSemana = semana.filter((c) => c._s === 'confirmada');
const faltasSemana = semana.filter((c) => c._s === 'falta');
const taxaConf = semana.length ? Math.round((confSemana.length / semana.length) * 100) : 0;

// --- escopo do gráfico: amanhã se houver; senão, a semana ---
const usaAmanha = deAmanha.length > 0;
const base = usaAmanha ? deAmanha : semana;
const tituloGrafico = usaAmanha
  ? `Consultas de amanhã (${fmtBR(amanha)})`
  : 'Consultas dos últimos 7 dias';

const gConf = base.filter((c) => c._s === 'confirmada').length;
const gAguard = base.filter((c) => c._s === 'aguardando resposta' || c._s === 'agendada').length;
const gOutros = base.filter((c) => ['cancelada', 'remarcada', 'falta'].includes(c._s)).length;

const chart = {
  type: 'doughnut',
  data: {
    labels: ['Confirmadas', 'Sem resposta', 'Canceladas/faltas'],
    datasets: [
      {
        data: [gConf, gAguard, gOutros],
        backgroundColor: ['#1FA36C', '#F5A524', '#9DB3AA'],
        borderColor: '#FAF7F2',
        borderWidth: 3,
      },
    ],
  },
  options: {
    plugins: {
      title: {
        display: true,
        text: tituloGrafico,
        color: '#0B3D2E',
        font: { size: 20, weight: 'bold' },
      },
      legend: { position: 'bottom', labels: { color: '#1C1C1C', font: { size: 14 } } },
      datalabels: {
        color: '#FFFFFF',
        font: { size: 20, weight: 'bold' },
      },
    },
  },
};

const chartUrl =
  'https://quickchart.io/chart?w=640&h=440&bkg=%23FAF7F2&c=' +
  encodeURIComponent(JSON.stringify(chart));

// --- texto ---
const rsGarantido = confAmanha.length * TICKET_MEDIO;
const rsRisco = aguardAmanha.length * TICKET_MEDIO;
const faltasEvitadas = Math.max(FALTAS_BASELINE - faltasSemana.length, 0);

let msg = `🌙 *${NOME_CLINICA} — fechamento do dia*\n${fmtBR(hoje)}\n\n`;

if (usaAmanha) {
  msg += `*Amanhã (${fmtBR(amanha)})*\n`;
  msg += `📅 ${deAmanha.length} consulta(s) na agenda\n`;
  msg += `✅ ${confAmanha.length} confirmada(s) — R$ ${reais(rsGarantido)} garantidos\n`;
  if (aguardAmanha.length > 0) {
    msg += `⏳ ${aguardAmanha.length} sem resposta — R$ ${reais(rsRisco)} em risco\n`;
  }
  if (cancAmanha.length > 0) {
    msg += `🔄 ${cancAmanha.length} cancelada(s)/remarcada(s) — horário livre para a lista de espera\n`;
  }
} else {
  msg += `*Amanhã (${fmtBR(amanha)})*\n📭 Nenhuma consulta agendada.\n`;
}

msg += `\n*Últimos 7 dias*\n`;
msg += `📊 Taxa de confirmação: ${taxaConf}% (${confSemana.length} de ${semana.length})\n`;
msg += `🚫 Faltas: ${faltasSemana.length}`;
if (faltasSemana.length > 0) msg += ` — R$ ${reais(faltasSemana.length * TICKET_MEDIO)} perdidos`;
msg += `\n`;
// só afirma "faltas evitadas" se houve movimento na semana — senão seria número inventado
if (faltasEvitadas > 0 && semana.length > 0) {
  msg += `💚 ~${faltasEvitadas} falta(s) evitada(s) vs. antes da automação — R$ ${reais(faltasEvitadas * TICKET_MEDIO)} preservados\n`;
}

if (aguardAmanha.length > 0) {
  msg += `\n*Vale uma ligação amanhã cedo:*\n`;
  msg += aguardAmanha.map((c) => `• ${c.paciente} — ${c.hora}`).join('\n');
  msg += `\n`;
}

msg += `\n_Relatório automático ModernEasy_`;

return [
  {
    json: {
      para: NUMERO_DO_DONO,
      caption: msg,
      grafico: chartUrl,
      _debug: {
        amanha: deAmanha.length,
        semana: semana.length,
        taxa: taxaConf,
        usouAmanha: usaAmanha,
      },
    },
  },
];
